/-- Exact order-dependent constant in the localization radius. -/
def Ak (k : ℕ) : ℝ :=
  (2 ^ (k + 4) * k.factorial : ℝ) ^ ((k - 2 : ℝ)⁻¹)

/-- The midpoint represented as a constant certified complex name. -/
def centeredExpCenterName (I : ComplexRatInterval) : CertifiedComplex :=
  CertifiedComplex.ofRatPair (rectangleMidpoint I).1 (rectangleMidpoint I).2

/-- Rational midpoint of a complex rectangle, coordinate by coordinate. -/
def rectangleMidpoint (I : ComplexRatInterval) : ℚ × ℚ :=
  (Transcendental.intervalMid I.re, Transcendental.intervalMid I.im)

/-- Deterministic perturbation scale of the selected population contour. -/
def adaptiveSelectorRatioConstant (p : Parameters) (pStar : CertifiedBankInputs p) : ℝ :=
  let aStar := ((contourBank p pStar).aStarRat : ℝ)
  ordinaryContourPerturbationConstant p (populationNumeratorEnvelope p)
    (31 * aStar / 64) (23 * aStar / 64)

/-- The explicit constant in the adaptive selector's inverse-sample-size MSE bound. -/
def adaptiveSelectorRiskConstant (p : Parameters) (pStar : CertifiedBankInputs p)
    (K : ℝ) : ℝ :=
  let aStar := ((contourBank p pStar).aStarRat : ℝ)
  let Lrat := adaptiveSelectorRatioConstant p pStar
  12 * Lrat ^ 2 * K + 1536 * p.Ctheta ^ 2 * K / aStar ^ 2 + 2

/-- Alternating-series remainder radius. -/
def atanRemainder (x : ℚ) (N : ℕ) : ℚ :=
  |x| ^ (2 * N + 3) / (2 * N + 3)

/-- The circle belonging to one bank radius. -/
def bankCircle (B : ContourBankData) (j : Fin (B.JBase + 1)) : Set ℂ :=
  sphere 0 (B.rho j) -- @realizes Cj(positively oriented circle |z|=rho_j)

/-- Clipped treatment code. -/
def barG (p : Parameters) (m : Model (Xspace := Xspace) p) (n : ℕ) (x : Xspace) : ℝ :=
  min (max (m.gcode n x) (-p.Cg)) p.Cg

/-- Clipped outcome code. -/
def barQ (p : Parameters) (m : Model (Xspace := Xspace) p) (n : ℕ) (x : Xspace) : ℝ :=
  min (max (m.qcode n x) (-p.Cq)) p.Cq

/-- One radius-`R` Blaschke factor. -/
def blaschkeFactor (R : ℝ) (a z : ℂ) : ℂ :=
  (R : ℂ) * (z - a) / ((R : ℂ) ^ 2 - star a * z)

/-- A finite radius-`R` Blaschke product. -/
def blaschkeProduct {N : ℕ} (R : ℝ) (a : Fin N → ℂ) (z : ℂ) : ℂ :=
  ∏ i, blaschkeFactor R (a i) z

/-- Fixed finite schedule for the corresponding circle tangent. -/
def circleTangentScheduleProgram (rName : ExecutablePositiveRealName)
    (N q : ℕ) (ε : PosRat) : CircleSchedule :=
  let budget := dividedTolerance ε (24 * (max N 1 + 1))
  let radiusFuel := rName.modulus budget
  let piFuel := machinPiFuel budget
  let angle : ComplexRatInterval :=
    ⟨RatInterval.point 0,
      (RatInterval.point (2 * q / max N 1)).mul (machinPiInterval piFuel)⟩
  { radiusTolerance := budget
    radiusFuel := radiusFuel
    piFuel := piFuel
    taylorFuel := cexpFuel angle budget }

/-- The normalized logarithmic-derivative integral used as the contour count. -/
def contourCount (F : ℂ → ℂ) (rho : ℝ) : ℂ :=
  normalizedLogDerivCircleIntegral F 0 rho

/-- Covariate marginal of the observed law. -/
def covariateLaw (p : Parameters) (m : Model (Xspace := Xspace) p) : Measure Xspace :=
  m.P.map covariate -- @realizes PX(covariate marginal of P)

/-- Complex conjugation negates the imaginary interval. -/
def cxConj (I : ComplexRatInterval) : ComplexRatInterval :=
  ⟨I.re, I.im.neg⟩

/-- Coordinatewise complex rectangle subtraction. -/
def cxSub (I J : ComplexRatInterval) : ComplexRatInterval :=
  ⟨I.re.sub J.re, I.im.sub J.im⟩

/-- Coordinatewise finite intersection of complex rectangles. -/
def cxTighten (I J : ComplexRatInterval) : ComplexRatInterval :=
  ⟨I.re.tighten J.re, I.im.tighten J.im⟩

/-- The uniform norm of a complex-valued random function on the closed disk of
radius `R`. -/
def diskSupNorm {Ω : Type*} (H : Ω → ℂ → ℂ) (R : ℝ) (ω : Ω) : ℝ :=
  sSup {x : ℝ | ∃ z : ℂ, ‖z‖ ≤ R ∧ x = ‖H ω z‖}

/-- Split empirical unweighted transform. -/
def empiricalF (data : Fin n → Obs Xspace) (I : Finset (Fin n)) (z : ℂ) : ℂ :=
  (I.card : ℂ)⁻¹ * ∑ i ∈ I, Complex.exp (z * learnedResidual p m n (data i))

/-- Treatment noise `T-g0(X)`. -/
def eta (p : Parameters) (m : Model (Xspace := Xspace) p) (o : Obs Xspace) : ℝ :=
  treatment o - m.g0 (covariate o) -- @realizes eta(T - g0(X))

/-- The deterministic lower and upper inference folds. -/
def fold0 (n : ℕ) : Finset (Fin n) :=
  Finset.univ.filter fun i ↦ i.1 < n / 2 -- @realizes I0(indices below floor n/2)

/-- The fourth cumulant, independent of the parameter field `k`. -/
def fourthCumulant (p : Parameters) (m : Model (Xspace := Xspace) p) : ℝ :=
  (iteratedDeriv 4 (fun z : ℂ ↦ Complex.log (complexMGF (eta p m) m.P z)) 0).re

