  0 < a →
    have t := Real.pi / (2 * a);
    have A := a * Real.exp (-(1 - a ^ 2) * Real.pi ^ 2 / (8 * a ^ 2));
    deriv (fun z => Complex.exp (↑(1 - a ^ 2) * z ^ 2 / 2) * Complex.cosh (↑a * z)) (Complex.I * ↑t) = Complex.I * ↑A

