∀ {Xspace : Type u_1} [inst : MeasurableSpace Xspace] (p : CausalSmith.Stat.SaPlmCumulantConverse.Parameters) (m : CausalSmith.Stat.SaPlmCumulantConverse.Model p) (n : ℕ),
  CausalSmith.Stat.SaPlmCumulantConverse.NonGaussianClass p n m →
    have R1 := CausalSmith.Stat.SaPlmCumulantConverse.searchRadius p;
    have eps0 := (4 * R1 * Real.exp (2 * p.Cg * R1))⁻¹;
    (∀ᵐ (o : CausalSmith.Stat.SaPlmCumulantConverse.Obs Xspace) ∂m.P, |CausalSmith.Stat.SaPlmCumulantConverse.treatmentError p m n o| ≤ 2 * p.Cg) ∧ ∫ (o : CausalSmith.Stat.SaPlmCumulantConverse.Obs Xspace), |CausalSmith.Stat.SaPlmCumulantConverse.treatmentError p m n o| ∂m.P ≤ p.eps1n n ∧ (∀ (z : ℂ), ‖z‖ ≤ R1 → ‖CausalSmith.Stat.SaPlmCumulantConverse.nuisanceMGF p m n z - 1‖ ≤ R1 * Real.exp (2 * p.Cg * R1) * p.eps1n n) ∧ (p.eps1n n ≤ eps0 → (∀ (z : ℂ), ‖z‖ ≤ R1 → 3 / 4 ≤ ‖CausalSmith.Stat.SaPlmCumulantConverse.nuisanceMGF p m n z‖) ∧ ∀ (z : ℂ), ‖z‖ ≤ R1 → analyticOrderAt (CausalSmith.Stat.SaPlmCumulantConverse.residualMGF p m n) z = analyticOrderAt (CausalSmith.Stat.SaPlmCumulantConverse.treatmentMGF p m) z)

