∀ {Xspace : Type u_1} [inst : MeasurableSpace Xspace] (compiled : CausalSmith.Stat.SaPlmCumulantConverse.CompiledBoundedSpectralAdapter) {p : CausalSmith.Stat.SaPlmCumulantConverse.Parameters} (pStar : CausalSmith.Stat.SaPlmCumulantConverse.CertifiedBankInputs p) (cStar : CausalSmith.Stat.SaPlmCumulantConverse.CertifiedRangeInput p) (gcode : ℕ → Xspace → ℝ),
  CausalSmith.Stat.SaPlmCumulantConverse.RepresentedExecution compiled p pStar cStar gcode →
    ∀ (data : Fin p.n → CausalSmith.Stat.SaPlmCumulantConverse.Obs Xspace),
      have input := CausalSmith.Stat.SaPlmCumulantConverse.canonicalRepresentedInput p pStar cStar gcode data;
      have result := CausalSmith.Stat.SaPlmCumulantConverse.representedSpectralProgram compiled input;
      result = CausalSmith.Stat.SaPlmCumulantConverse.ordinaryFiniteRationalResult p pStar cStar gcode data ∧ result.trace = (CausalSmith.Stat.SaPlmCumulantConverse.thetaHatSpec p pStar cStar gcode).fullTrace data ∧ result.output.IsCertified ((CausalSmith.Stat.SaPlmCumulantConverse.thetaHatSpec p pStar cStar gcode).ordinaryValue data)

