/-- Closed-form finite empirical-map fuel. -/
def spectralEmpiricalMapFuel (tolerance : PosRat) (operations : ℕ) (L : ℚ) : ℕ :=
  64 * (operations + 1) * (tolerance.1.den + 1) * (L.num.natAbs + 2) ^ 2

/-- Rational lower bound for the square of every point of an interval. -/
def sqLo (I : RatInterval) : ℚ :=
  if I.lo ≤ 0 ∧ 0 ≤ I.hi then 0 else min (I.lo ^ 2) (I.hi ^ 2)

/-- Fixed-fuel upper square-root bisection. -/
def sqrtHiBisect (x : ℚ) (fuel : ℕ) : ℚ :=
  (Nat.iterate (sqrtLoStep x) fuel (sqrtInitial x)).hi

/-- Fixed-fuel lower square-root bisection. -/
def sqrtLoBisect (x : ℚ) (fuel : ℕ) : ℚ :=
  (Nat.iterate (sqrtLoStep x) fuel (sqrtInitial x)).lo

/-- The uniform error of a random transform against a fixed target on a disk: the supremum,
over all complex points of modulus at most the given radius, of the distance between the value
of the random transform at that point and the value of the target there. -/
def transformSupError (Fhat : Ω → ℂ → ℂ) (F : ℂ → ℂ)
    (R : ℝ) (w : Ω) : ℝ :=
  sSup {x : ℝ | ∃ z : ℂ, ‖z‖ ≤ R ∧ x = ‖Fhat w z - F z‖}

/-- Weighted bilateral exponential transform. -/
def weightedTransform [MeasurableSpace Ω] (P : Measure Ω) (W V : Ω → ℝ) (z : ℂ) : ℂ :=
  ∫ w, (W w : ℂ) * Complex.exp (z * V w) ∂P

/-- The sigma-algebra generated by `(X,T)`. -/
def xTSigma : MeasurableSpace (Obs Xspace) :=
  MeasurableSpace.comap (fun o : Obs Xspace ↦ (covariate o, treatment o)) inferInstance

/-- Outcome noise `Y-q0(X)-theta0*eta`. -/
def xi (p : Parameters) (m : Model (Xspace := Xspace) p) (o : Obs Xspace) : ℝ :=
  outcome o - m.q0 (covariate o) - m.theta0 * eta p m o

/-- The fixed covariate-treatment marginal used by an affine outcome path. -/
def xtLaw {p : Parameters} (base : Model (Xspace := Xspace) p) : Measure (XT Xspace) :=
  base.P.map (fun o ↦ (covariate o, treatment o))

/-- Explicit transform-zero localization radius. -/
def zeroRadius (p : Parameters) : ℝ :=
  Ak p.k * (p.psieta ^ 2 / p.delta) ^ ((p.k - 2 : ℝ)⁻¹)
